content.content:
1	/* ============================ Đi dạo: điều phối chế độ (một mình hoặc nhiều người, máy tính) ============================
2	   Nối bản đồ va chạm (map / mapData / sceneData), chuyển động (motion), nhân vật (avatars), camera sau lưng (camera) với vòng animate, phím, chuột.
3	   `?explore=stroll` vào thẳng, đi một mình (explore/index.ts gọi start). Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020).
4	   - Bản đồ dựng lần đầu vào chế độ: dữ liệu tĩnh + nhà / chân đế thu từ cảnh đã dựng (chỉ đọc, sau mọi rand()).
5	   - Nhịp quay Cầu sông Hàn đóng với người đi dạo khi cầu rời trạng thái CLOSED (spec §3 mục 13); không tự quay, không tăng tốc quay.
6	   - Ban đêm Cầu Rồng tự phun như khi bay dù (exNightStep, không đụng cầu quay).
7	   - Nhảy theo cạnh: một lần bấm Space một lần nhảy, giữ Space không nhảy liên tục (stStep nhảy mỗi khung jump = true khi chạm đất).
8	   - Phím chỉ ghi khi đang đi dạo, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì xóa hết phím (Review Focus 3).
9	   - Nhiều người (exMulti, phiên kind 'walk'): xuất phát theo slot đi dạo, gửi vị trí + dáng; hết chỗ thì chế độ xem (startWatching) đặt camera sau lưng người được xem.
10	     Đổi phiên như dù lượn: bị thu chỗ → xem; mất kết nối khi đang đi → đi tiếp một mình + thông báo; mất kết nối khi xem → thoát, màn chọn báo mất kết nối.
11	   - Rời máy: phím điều khiển, kéo chuột và chạm cảm ứng gọi exMulti.activity().
12	   - Cảm ứng (touch.ts, #stHud): cần gạt ghi đè phím khi đang được giữ; vuốt nửa phải xoay camera; chạm Nhảy là một lần nhảy (như một lần bấm Space); 📷 gọi stPhoto (Task 9 điền).
13	   Mỗi khung không cấp phát (D-018). */
14	import { scene, camera, controls, canvas } from '../../core/renderer';
15	import { cam, keys } from '../../views/state';
16	import { CONFIG } from '../../config';
17	import { stSetGate, type StMap } from './map';
18	import { ST_GATE_SWING, stBuildStaticMap } from './mapData';
19	import { stCreate, stStep, type StState, type StInput } from './motion';
20	import { stAvatars } from './avatars';
21	import { stCollectRuntime } from './sceneData';
22	import { stCamPlace, stCamDrag, type StCam } from './camera';
23	import { stInputFromKeys } from './keys';
24	import { stTouchBind } from './touch';
25	import { exNightStep } from '../nightShows';
26	import { exMulti } from '../multi';
27	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
28	import type { SwingController } from '../../bridges/song-han/SwingController';
29	
30	const ST_SOLO_SLOT = -1;     // stCreate / stSpawn: đi một mình đứng giữa các điểm xuất phát
31	const ST_SOLO_AVATAR = 0;    // instance nhân vật khi đi một mình (avatars.ts)
32	
33	let map: StMap | null = null;
34	let state: StState | null = null;
35	let ctrl: SwingController | null = null;
36	let exit: () => void = () => {};   // thoát chung (explore.exit), do setupStroll nhận
37	let jumpQueued = false;      // Space vừa được bấm (không phải tự lặp): khung sau nhảy một lần
38	let selfSlot = ST_SOLO_AVATAR;   // instance nhân vật của mình: slot đi dạo khi có chỗ, giữ nguyên khi mất kết nối (màu áo không đổi)
39	let watching = false;        // đang xem người khác đi dạo (hết chỗ hoặc vừa nhường chỗ): không có nhân vật của mình, không đọc phím
40	let touch: ReturnType<typeof stTouchBind> | null = null;   // điều khiển cảm ứng (setupStroll dựng)
41	let chased = false;          // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
42	const camS: StCam = { yaw: 0, pitch: CONFIG.stroll.cam.pitch };
43	const _inp: StInput = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };   // đầu vào tái dùng mỗi khung
44	
45	const active = () => cam.mode === 'stroll' && state !== null;
46	const inMode = () => active() || watching;   // Esc và giao diện đi dạo áp cho cả chế độ xem
47	/* Chụp ảnh (nút 📷, máy tính và cảm ứng): Task 9 điền. Hiện chưa làm gì */
48	function stPhoto(): void { /* Task 9: chụp canvas, lưu file, chớp màn hình */ }
49	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
50	
51	/* Một bước: cổng nhịp quay, chuyển động, nhân vật, camera, hiệu ứng đêm, người chơi khác */
52	function advance(dt: number, inp: StInput): void {
53	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
54	  stStep(state!, inp, map!, dt);
55	  stAvatars.setSelf(selfSlot, state);
56	  stCamPlace(camera, controls.target, state!, camS, map!, dt);
57	  exNightStep(dt, false);
58	  const now = performance.now();
59	  exMulti.update(dt, now, null);   // người khác (đi dạo + bay), nhãn tên; không làm gì khi đi một mình
60	  exMulti.updateWalk(now, state);  // gửi vị trí + dáng khi đang giữ chỗ
61	}
62	
63	/* Mỗi khung khi xem: người khác, nhãn, danh sách; camera sau lưng người được xem (hướng camera = hướng mặt họ). Không có ai thì camera giữ nguyên */
64	function watchStep(dt: number): void {
65	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
66	  exMulti.update(dt, performance.now(), null);
67	  const w = exMulti.watchWalker();
68	  if (w) { camS.yaw = w.yaw; stCamPlace(camera, controls.target, w, camS, map!, dt, !chased); chased = true; }
69	  exNightStep(dt, false);
70	}
71	
72	/* Đổi phiên khi đang xem hoặc đang đi: vào đi, mất kết nối, bị thu hồi chỗ (như onMultiChange của dù lượn) */
73	function stOnMultiChange(): void {
74	  const s = exMulti.session; if (!s) return;
75	  if (watching) {
76	    if (s.phase === 'flying') { stroll.start(); return; }   // chấp nhận lời mời: xuất phát như vào đi thường
77	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
78	    exWatchRender();
79	  } else if (active()) {
80	    if (s.phase === 'watching') { state = null; stAvatars.setSelf(selfSlot, null); stroll.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
81	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'stLost');   // vẫn đi, người khác đã biến mất
82	  }
83	}
84	
85	/* Bản đồ dựng lần đầu vào chế độ (đi hoặc xem); cổng nhịp quay theo cầu hiện tại */
86	function stEnsureMap(): StMap {
87	  if (!map) { map = stBuildStaticMap(); stCollectRuntime(map); }
88	  if (ctrl) stSetGate(map, ST_GATE_SWING, ctrl.state !== 'CLOSED');
89	  return map;
90	}
91	
92	export const stroll = {
93	  active,
94	  inMode,
95	  get watching(): boolean { return watching; },
96	  get state(): StState | null { return state; },
97	  get map(): StMap | null { return map; },
98	  get cam(): StCam { return camS; },
99	  /* Vào đi: một mình (không phiên / ngoại tuyến) hoặc với slot đi dạo vừa được cấp (xuất phát lệch theo slot) */
100	  start(): void {
101	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
102	    const m = stEnsureMap(), s = exMulti.session;
103	    const slot = s && s.kind === 'walk' && s.mySlot >= 0 ? s.mySlot : ST_SOLO_SLOT;
104	    if (s) exMulti.onChange = stOnMultiChange;
105	    selfSlot = slot >= 0 ? slot : ST_SOLO_AVATAR;
106	    state = stCreate(m, slot);
107	    camS.yaw = state.yaw; camS.pitch = CONFIG.stroll.cam.pitch;
108	    const mesh = stAvatars.build();
109	    if (!mesh.parent) scene.add(mesh);
110	    stAvatars.setSelf(selfSlot, state);
111	    keys.clear(); jumpQueued = false; if (touch) touch.reset();
112	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
113	    stCamPlace(camera, controls.target, state, camS, m, 0, true);
114	    document.body.classList.add('explore', 'stroll');
115	  },
116	  /* Chế độ xem: cam.mode = 'stroll' nhưng không có nhân vật của mình; carry = true khi vừa nhường chỗ (camera đang ở sau lưng mình, trượt dần sang người được xem) */
117	  startWatching(carry = false): void {
118	    const s = exMulti.session; if (!s) return;
119	    stEnsureMap();
120	    const mesh = stAvatars.build();
121	    if (!mesh.parent) scene.add(mesh);
122	    watching = true; chased = carry; state = null;
123	    keys.clear(); jumpQueued = false;
124	    camS.pitch = CONFIG.stroll.cam.pitch;
125	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
126	    document.body.classList.add('explore', 'stroll', 'ex-watching');
127	    exMulti.onChange = stOnMultiChange;
128	    exWatchShow(s);
129	  },
130	  update(dt: number): void {
131	    if (watching) { watchStep(dt); return; }
132	    if (!active()) return;
133	    stInputFromKeys(keys, camS.yaw, _inp);
134	    if (touch) touch.read(_inp);   // cần gạt đang giữ thì ghi đè hướng và chạy của phím
135	    _inp.jump = jumpQueued; jumpQueued = false;
136	    advance(dt, _inp);
137	  },
138	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
139	  step(dt: number, inp: StInput): void {
140	    if (active()) advance(dt, inp);
141	  }
142	};
143	
144	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
145	export function setupStroll(c: SwingController, onExit: () => void): void {
146	  ctrl = c; exit = onExit;
147	  window.addEventListener('keydown', (e) => {
148	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung); đang xem: không đọc phím
149	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển nhân vật, tránh kẹt phím
150	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển nhân vật
151	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
152	    const k = e.key.toLowerCase();
153	    if (k === ' ') { e.preventDefault(); if (!e.repeat) jumpQueued = true; }
154	    else if (k.startsWith('arrow')) e.preventDefault();
155	    keys.add(k);
156	  });
157	  window.addEventListener('keyup', (e) => {
158	    keys.delete(e.key.toLowerCase());
159	    if (e.key === ' ' && active() && !isField(e.target)) e.preventDefault();   // Space không bấm nút đang focus
160	  });
161	  const drop = () => { keys.clear(); jumpQueued = false; };
162	  window.addEventListener('blur', drop);
163	  document.addEventListener('visibilitychange', () => { if (document.hidden) drop(); });
164	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
165	  const hud = document.getElementById('stHud');
166	  if (hud) touch = stTouchBind(hud, {
167	    look: (dx, dy) => { if (active()) stCamDrag(camS, dx, dy, CONFIG.stroll.cam.touch); },
168	    jump: () => { if (active()) jumpQueued = true; },
169	    photo: stPhoto,
170	    activity: () => exMulti.activity()
171	  });
172	  /* Kéo chuột trái trên canvas: xoay camera (cảm ứng ở Task 8) */
