11	//   Mục 6: phím W theo hướng camera, blur dừng (Review Focus 3), gõ trong ô nhập không điều khiển, Space một lần nhảy một lần, Esc thoát.
12	//   Trang B `?test`: không có `stroll-people` trong cảnh.
13	//   Mục 9 (Task 7): sảnh đi dạo qua màn chọn với máy chủ giả (routeWebSocket): chữ đi dạo, đổi ngôn ngữ ar / en đổi ngay, Quay lại → Dù lượn về chữ dù lượn,
14	//          máy chủ cũ (lobby không walkers) → ngoại tuyến, Đi một mình.
15	//   Mục 10 (Task 7): cả 9 file locale có đủ khóa st* và exWalk / exWalkDesc.
16	//
17	//   npm run build && npm run test:stroll
18	//
19	//   Oracle mục 3 (không dùng bản đồ va chạm): tam giác thế giới của các lưới rắn, xếp vào lưới ô 2 m để chỉ thử tam giác gần nhân vật
20	//   (Raycaster trên cả cảnh với 24 000 tia không xong trong thời gian hợp lý trên SwiftShader). Thử tia bằng Ray.intersectTriangle
21	//   không loại mặt sau = vật liệu DoubleSide. Lưới dùng: nhà level gần của THREE.LOD (InstancedMesh, mọi instance còn hiện quanh khung đi dạo),
22	//   `dragon-body` (thân rồng), `dragon-head` (cả nhóm đầu rồng), `sh-tower` (tháp Cầu sông Hàn), `rf-landmarks` (địa danh ven sông, gồm cả
23	//   cầu tàu, lan can, hàng khóa và tượng cá chép Cầu Tình Yêu). Không dùng: cây, cột đèn, ghế, xe, người, dây văng, bảng quảng cáo (spec §4: đi xuyên được).
24	//   Cao độ tia tính từ cao độ đứng tại chỗ (không từ chân khi đang nhảy): spec chỉ chặn trong tầm người tính từ mặt đứng.
25	import { fileURLToPath } from 'node:url';
26	import { readFileSync } from 'node:fs';
27	import { serveDir, launch, openApp, frames } from './lib.mjs';
28	
29	const problems = [];
30	const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };
31	
32	/* Chạy trong trang: hàm dùng chung (đặt nhân vật, tìm vùng, tia thẳng xuống) */
33	function installHelpers() {
34	  const a = window.__app, S = a.stroll, T = a.THREE;
35	  const map = () => S.stroll.map;
36	  const zoneAt = (x, z) => {
37	    for (const zn of map().zones) {
38	      if (x < zn.x0 || x > zn.x1 || z < zn.z0 || z > zn.z1) continue;
39	      if (zn.gate !== undefined && map().closed.has(zn.gate)) continue;
40	      return zn;
41	    }
42	    return null;
43	  };
44	  const put = (x, z) => {
45	    const s = S.stroll.state, g = S.stGroundY(map(), x, z);
46	    s.x = x; s.z = z; s.y = g; s.vy = 0; s.air = false; s.evac = false; s.speed = 0; s.tx = x; s.tz = z; s.photo = 0;
47	    return g;
